  "accents": []
};

export const meta = {
  "slug": "phosphor-arrow-up-left",
  "family": "phosphor",
  "name": "arrow-up-left",
  "category": "Navigation",
  "motion": "slideLeft",
  "component": "createPhosphorArrowUpLeftIcon"
};

export function createPhosphorArrowUpLeftIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
